// S4 -- formulario curto de libertacao de slot (Tally: NIF + link + confirmacao).
// Ver docs/SCHEMA_TALLY_LIBERTAR.md e STATE.md.
const tallyBody = $json.body || {};
const isTally = !!tallyBody.data?.fields;

function normalizeLabel(s) {
  return String(s || '')
    .normalize('NFD').replace(/[\u0300-\u036f]/g, '')
    .toLowerCase()
    .replace(/\s+/g, ' ')
    .trim();
}
function getField(primaryLabel) {
  if (!isTally) return null;
  const c = normalizeLabel(primaryLabel);
  return tallyBody.data.fields.find(f => f.label && normalizeLabel(f.label).includes(c));
}
function getValue(primaryLabel, directKey) {
  const f = getField(primaryLabel);
  if (f) {
    if (Array.isArray(f.value)) return f.value[0] ?? '';
    return f.value || '';
  }
  return tallyBody[directKey] !== undefined ? tallyBody[directKey] : '';
}

const nifRaw = getValue('NIF', 'nif') || '';
const nif = String(nifRaw).replace(/\D/g, '');
const link = getValue('Link da Página a Libertar', 'link') || '';
const confirmacaoRaw = getValue('Confirmação', 'confirmacao') || '';
const confirmacao = /^(sim|yes|true|confirmo)$/i.test(String(confirmacaoRaw).trim());

const emFalta = [];
if (!nif) emFalta.push('NIF');
if (!link) emFalta.push('Link da Página a Libertar');
if (!confirmacao) emFalta.push('Confirmação (tem de confirmar explicitamente)');
if (emFalta.length) {
  throw new Error('LIBERTAR SLOT: campo(s) em falta ou invalido(s) -- ' + emFalta.join(', ') + '. Execução falhada.');
}

const m = String(link).match(/([a-z0-9-]+\.html)(?:\?.*)?$/i);
if (!m) {
  throw new Error('LIBERTAR SLOT: nao foi possivel identificar o ficheiro a partir do link fornecido: ' + link);
}
const fileNameAlvo = m[1];

return [{ json: { nif, fileNameAlvo } }];

const payload = $('Prepara Payload Libertar').item.json;
const nif = payload.nif;
const fileNameAlvo = payload.fileNameAlvo;

let clientes = {};
try {
  const buf = await this.helpers.getBinaryDataBuffer(0, 'clientes');
  clientes = JSON.parse(buf.toString('utf8'));
} catch (e) {
  throw new Error('LIBERTAR SLOT: nao foi possivel ler o registo de clientes.');
}

const cliente = clientes[nif];
if (!cliente) {
  throw new Error('LIBERTAR SLOT: NIF ' + nif + ' nao encontrado no registo de clientes.');
}
const paginas = Array.isArray(cliente.paginas) ? cliente.paginas : [];
const idx = paginas.findIndex(p => p && p.fileName && p.fileName.endsWith(fileNameAlvo));
if (idx === -1) {
  throw new Error('LIBERTAR SLOT: imovel "' + fileNameAlvo + '" nao encontrado nas paginas publicadas do NIF ' + nif + '.');
}
const [pagina] = paginas.splice(idx, 1);
cliente.paginas = paginas;

const out = Buffer.from(JSON.stringify(clientes, null, 2), 'utf8');
return [{
  json: {
    nif,
    tituloLiberado: pagina.titulo,
    stateFileNameAlvo: pagina.stateFileName,
    fileNameAlvo: pagina.fileName,
    slotsLivres: (cliente.slots_total || 0) - paginas.filter(p => p && p.estado === 'publicado').length
  },
  binary: { clientesOut: await this.helpers.prepareBinaryData(out, 'clientes.json', 'application/json') }
}];

// Despublica a landing: substitui o HTML por um aviso e marca o state como
// despublicado (best-effort -- se o ficheiro ja nao existir, o slot ja foi
// libertado no passo anterior de qualquer forma, o que e o que importa).
// Le o state.json via HTTP (o proprio nginx que serve /var/www/prisma-builds)
// em vez de um no readWriteFile de leitura: um ficheiro em falta com
// continueOnFail produz ZERO itens de saida nesta instancia de n8n (confirmado
// por teste direto), o que mataria este ramo em silencio e faria o webhook
// responder "No item to return was found" mesmo tendo o slot sido libertado
// com sucesso no passo anterior. Um try/catch dentro do MESMO no evita isso.
const info = $('Liberta Slot').item.json;
let state = null;
try {
  const buf = await this.helpers.httpRequest({ url: 'http://161.35.19.139/' + info.stateFileNameAlvo, encoding: 'arraybuffer' });
  state = JSON.parse(Buffer.from(buf).toString('utf8'));
} catch (e) { state = null; }
const tituloEsc = String((state && state.imovel && state.imovel.titulo) || info.tituloLiberado || 'Este imóvel')
  .replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');

const html = `<!DOCTYPE html>
<html lang="pt">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>Imóvel já não disponível</title>
<meta name="robots" content="noindex">
<style>
  body{font-family:system-ui,sans-serif;background:#0f172a;color:#f8fafc;display:flex;min-height:100vh;align-items:center;justify-content:center;margin:0;padding:1.5rem;text-align:center}
  .box{max-width:32rem}
  h1{font-size:1.5rem;margin-bottom:.75rem}
  p{color:#94a3b8;line-height:1.6}
</style>
</head>
<body>
  <div class="box">
    <h1>"${tituloEsc}" já não está disponível</h1>
    <p>Este imóvel foi retirado pelo corretor — provavelmente porque já foi vendido ou arrendado.</p>
  </div>
</body>
</html>`;

if (state) state.estado = 'despublicado';

const htmlBin = await this.helpers.prepareBinaryData(Buffer.from(html, 'utf8'), info.fileNameAlvo, 'text/html');
const out = { json: { fileName: '/home/node/.n8n-files/builds/' + info.fileNameAlvo }, binary: { data: htmlBin } };

if (state) {
  const stateBin = await this.helpers.prepareBinaryData(Buffer.from(JSON.stringify(state, null, 2), 'utf8'), info.stateFileNameAlvo, 'application/json');
  out.json.stateFileName = '/home/node/.n8n-files/builds/' + info.stateFileNameAlvo;
  out.binary.state = stateBin;
}

return [out];
